-- ============================================================
-- SEED EXT 3: Módulo 18 — Nominalization (ex 106-205)
-- Novos tópicos: -ing nominalization, de-nominalization,
-- N+of+N chains, complex TOEFL production
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'nominalization';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo nominalization não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: -ing nominalization as process noun
  (cid,31,106,'gap_fill','The _____ (test) of the new vaccine required three phases and over 10,000 participants.','testing',NULL,'"The testing of" = -ing nominalization as process noun. Refers to the procedure itself.','medium'),
  (cid,31,107,'multiple_choice','In "The training of healthcare workers is a critical priority," "training" functions as:','A gerund/nominalization (subject of the sentence, referring to the process).','["An adjective modifying healthcare workers","A verb in continuous tense","A gerund/nominalization (subject of the sentence, referring to the process).","A participial phrase"]','"The training of X" = -ing nominalization = noun phrase (process noun).','medium'),
  (cid,31,108,'gap_fill','The _____ (fund) of basic science research has declined significantly in recent decades.','funding',NULL,'"The funding of" = -ing nominalization.','easy'),
  (cid,31,109,'gap_fill','_____ (map) the human genome represented the greatest scientific achievement of the 20th century. (subject = process)','Mapping',NULL,'"Mapping" as gerund/nominalization = subject of sentence. Refers to the entire enterprise.','medium'),
  (cid,31,110,'multiple_choice','Which sentence uses an -ing nominalization MOST effectively in academic writing?','The processing of environmental data requires specialized computational tools.','["We process environmental data using specialized computational tools.","Processing environmental data, we use specialized tools.","The processing of environmental data requires specialized computational tools.","They processed environmental data with specialized computational tools."]','"The processing of" = -ing nominalization creates formal, impersonal academic subject.','hard'),
  (cid,31,111,'gap_fill','The _____ (sample) of deep-ocean sediment cores provided evidence of historical climate shifts.','sampling',NULL,'"The sampling of" = process nominalization.','medium'),
  (cid,31,112,'gap_fill','Effective _____ (monitor) of patient vital signs during surgery can prevent complications.','monitoring',NULL,'"Monitoring of" = -ing nominalization. "Effective monitoring of X" is a standard academic phrase.','easy'),

  -- BLOCK 32: de-nominalization (when NOT to nominalize)
  (cid,32,113,'multiple_choice','Which sentence should be DE-nominalized to improve clarity?','The occurrence of the disappearance of the substance from the solution was observed.','["The researchers analyzed the effects of the intervention.","The occurrence of the disappearance of the substance from the solution was observed.","The implementation of the policy reduced costs.","The measurement of temperature proved difficult."]','Triple nominalization (occurrence + disappearance + solution) = opaque. Better: "We observed that the substance disappeared from the solution."','hard'),
  (cid,32,114,'gap_fill','Over-nominalized: "The teacher conducted an evaluation of the performance of the students." Better: "The teacher _____ the students'' performance."','evaluated',NULL,'De-nominalize when simplicity and directness are more appropriate (e.g., informal reports).','medium'),
  (cid,32,115,'multiple_choice','When is it better to use a verb instead of a nominalization?','When writing instructions, narratives, or informal reports where directness and clarity are priorities.','["In all academic writing","When writing instructions, narratives, or informal reports where directness and clarity are priorities.","Nominalizations should always be preferred","Only in spoken language"]','Context determines register: academic writing → nominalize; instructions/narrative → verbs.','hard'),
  (cid,32,116,'gap_fill','Over-nominalized: "There was a significant reduction in the utilization of resources by the organization." Better: "The organization _____ resources significantly.','used fewer',NULL,'De-nominalization: "utilized" → "used" and "reduction in utilization" → "used fewer."','medium'),
  (cid,32,117,'multiple_choice','Which sentence is CLEARER and SIMPLER (appropriately de-nominalized for an instruction manual)?','Press the button to activate the system.','["The depression of the button results in activation of the system.","Press the button to activate the system.","The button''s depression leads to system activation.","The pressing of the button causes the activation of the system."]','Instruction manuals require clear, verb-based language. Not nominalized academic prose.','medium'),
  (cid,32,118,'gap_fill','Simplify: "The implementation of the recommendation will result in an improvement in the performance of the system." → "_____ the recommendation will improve the system.','Implementing',NULL,'"Implementing" (gerund) replaces "the implementation of" — preserves formality with less opacity.','hard'),

  -- BLOCK 33: N+of+N nominalization chains
  (cid,33,119,'gap_fill','The _____ (rate) of _____ (increase) of global temperatures over the past century is unprecedented.','rate / increase',NULL,'"The rate of increase of X" = N+of+N+of+N nominalization chain.','hard'),
  (cid,33,120,'multiple_choice','Which nominalization chain is grammatically correct?','The degree of accuracy of the measurement determines the reliability of the findings.','["The degree of the accuracy of the measurement of the reliability of the findings determines it.","The degree of accuracy of the measurement determines the reliability of the findings.","The degree of accurate of the measure determines the reliability of findings.","The accurately degree of measurement determines reliability."]','"The degree of accuracy of the measurement" = valid two-level N+of+N chain.','hard'),
  (cid,33,121,'gap_fill','The _____ (level) of _____ (participate) in the study was higher than expected.','level / participation',NULL,'"The level of participation of" — N+of+N chain describing degree.','medium'),
  (cid,33,122,'multiple_choice','When do N+of+N chains become problematic?','When they create 3+ levels of nested nominalizations that obscure the main meaning.','["When they contain more than 2 nouns","When they are used in any academic text","When they create 3+ levels of nested nominalizations that obscure the main meaning.","When the nouns are all abstract"]','Two-level chains are acceptable; three or more can become opaque.','hard'),
  (cid,33,123,'gap_fill','The _____ (extent) of the _____ (damage) caused by the storm was not immediately apparent.','extent / damage',NULL,'"The extent of the damage" — common academic N+of+N chain.','easy'),
  (cid,33,124,'gap_fill','The _____ (speed) of _____ (adopt) of new technologies varies significantly between regions.','speed / adoption',NULL,'"The speed of adoption of X" — two-level nominalization chain.','hard'),

  -- BLOCK 34: possession and nominalization
  (cid,34,125,'gap_fill','___ (Darwin) _____ (propose) of the theory of natural selection transformed biology. (use possessive + nominalization)','Darwin''s proposal',NULL,'"Darwin''s proposal of" = possessive + nominalization. More concise than "The proposal that Darwin made."','hard'),
  (cid,34,126,'multiple_choice','Which is the most concise and formal nominalized version of "The government decided that they would reform the system"?','The government''s decision to reform the system...','["The government decided to reform the system (verb — simpler but less formal as a subject phrase)","The government''s decision to reform the system...","The decision of the government that they would reform the system...","The fact that the government decided to reform the system..."]','Possessive + nominalization = concise, formal, suitable as a subject phrase.','hard'),
  (cid,34,127,'gap_fill','___ (committee) _____ (endorse) of the proposal cleared the way for implementation.','The committee''s endorsement',NULL,'"The committee''s endorsement of" = possessive + -ment nominalization.','hard'),
  (cid,34,128,'multiple_choice','Transform: "When the economy grew, public health improved." → possessive nominalization?','Economic growth led to an improvement in public health.','["Economy growth led to health improvement.","Economic growth led to an improvement in public health.","The growth of economy led to health''s improvement.","The growing of economy led to the improvement of health."]','"Economic growth" (adj+noun) + "improvement in" = double nominalization, formal.','hard'),

  -- BLOCK 35: nominalization in TOEFL integrated tasks
  (cid,35,129,'multiple_choice','[TOEFL] "The introduction of genetically modified organisms has accelerated the development of drought-resistant crops." How many nominalizations are in this sentence?','Two: introduction and development.','["One: introduction","Two: introduction and development.","Three: introduction, development, and organisms","Four: introduction, organisms, development, crops"]','"Introduction" (introduce → noun) and "development" (develop → noun).','medium'),
  (cid,35,130,'gap_fill','[TOEFL Reading] "The _____ (discover) of the Higgs boson in 2012 confirmed a key prediction of the Standard Model." Best nominalization?','discovery',NULL,'"The discovery of" = irregular nominalization (discover → discovery).','easy'),
  (cid,35,131,'multiple_choice','[TOEFL Reading] "The gradual erosion of soil nutrients reduces the productive capacity of agricultural land." Identify the two key nominalizations.','Erosion and capacity.','["Gradual and productive","Erosion and capacity.","Reduces and land","Nutrients and soil"]','"Erosion" (erode → noun) and "capacity" (capable → noun).','medium'),
  (cid,35,132,'gap_fill','[TOEFL] Rewrite using nominalization: "Scientists discovered that carbon dioxide absorbs heat." → "The _____ (discover) that carbon dioxide _____ (absorb) heat has important climate implications."','discovery / absorbs',NULL,'"The discovery that" + subject clause. Only "discovery" is nominalized; the that-clause retains its verb.','hard'),
  (cid,35,133,'multiple_choice','[TOEFL] "The proliferation of social media platforms has led to a transformation in the way information spreads." Which word is NOT a nominalization?','Spreads','["Proliferation","Transformation","Information","Spreads"]','"Spreads" is a verb in the relative clause. Proliferation, transformation, and information are all nominalizations.','hard'),

  -- BLOCK 36: advanced academic nominalization practice
  (cid,36,134,'gap_fill','The _____ (establish) of international trade agreements requires careful _____ (negotiate) between member states.','establishment / negotiation',NULL,'Two nominalizations: establishment (-ment) + negotiation (-tion).','medium'),
  (cid,36,135,'multiple_choice','Which sentence demonstrates the HIGHEST degree of nominalization typical of academic prose?','The intensification of economic competition has led to a rapid acceleration in the adoption of automation technologies across manufacturing sectors.','["Companies are competing more intensively, so they are adopting automation faster.","The intensification of economic competition has led to a rapid acceleration in the adoption of automation technologies across manufacturing sectors.","There is more competition, so companies are automating more quickly.","Economic competition has intensified, accelerating automation adoption."]','Multiple nominalizations: intensification, competition, acceleration, adoption — all in one sentence.','hard'),
  (cid,36,136,'gap_fill','The _____ (combine) of qualitative and quantitative methods strengthens the _____ (valid) of research findings.','combination / validity',NULL,'"Combination" (-ation) and "validity" (-ity) = two nominalizations.','medium'),
  (cid,36,137,'multiple_choice','Why does academic writing in sciences favor nouns (nominalization) over verbs?','Nominalizations allow writers to treat complex processes as entities that can be modified, quantified, and positioned as subjects or objects in arguments.','["Scientists cannot use verbs in their writing","Nominalizations are always shorter","Nominalizations allow writers to treat complex processes as entities that can be modified, quantified, and positioned as subjects or objects in arguments.","Verbs are informal"]','Nominalization = syntactic maneuverability — the process becomes a noun that can be argued about.','hard'),
  (cid,36,138,'gap_fill','The successful _____ (complete) of this study depended on the _____ (cooperate) of three national health ministries.','completion / cooperation',NULL,'"Completion" (-tion) and "cooperation" (-tion).','easy'),

  -- BLOCK 37: TOEFL Speaking
  (cid,37,139,'production','[TOEFL Speaking — 45s] A reading discusses how urbanization leads to environmental problems. Summarize using nominalizations: the growth of, the expansion of, the reduction in, the deterioration of, the implementation of.','',NULL,'The rapid growth of urban populations has led to a significant expansion of built-up areas into previously natural habitats. This has resulted in a reduction in biodiversity and a deterioration of air and water quality in many major cities. The implementation of sustainable urban planning policies is increasingly recognized as essential to mitigating these effects.','hard'),
  (cid,37,140,'production','[TOEFL Speaking — 45s] A professor argues that schools should teach critical thinking as a distinct subject. Agree or disagree using nominalizations: the development of, the integration of, the acquisition of, the assessment of.','',NULL,'The development of critical thinking skills is undeniably important, but I believe their integration into existing subjects is more effective than creating a separate course. The acquisition of analytical skills occurs most naturally in context — when students evaluate historical evidence in history class or assess experimental data in science. The assessment of critical thinking across disciplines would also be more authentic and meaningful than measuring it in isolation.','hard'),

  -- BLOCK 38: TOEFL Writing
  (cid,38,141,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "The consequences of income inequality" using at least 6 nominalizations. Underline each one.','',NULL,'The persistence of income inequality represents one of the most pressing challenges facing contemporary societies. The concentration of wealth among a small proportion of the population limits the social mobility of the majority and undermines the cohesion of communities. Research has demonstrated a clear association between economic inequality and the deterioration of health outcomes, particularly in regions where access to healthcare is itself tied to financial capacity. The reduction of inequality requires the implementation of redistributive policies, including progressive taxation and investment in public education. Without sustained commitment to such reforms, the perpetuation of structural disadvantage is inevitable. The measurement of inequality through indices such as the Gini coefficient allows policymakers to track progress and evaluate the effectiveness of interventions.','hard'),
  (cid,38,142,'production','[TOEFL Writing — Error Correction] Fix nominalization errors: "The grow of the economy is important. The succeed of the project depended on cooperate. The fail of the medicine to work led to more tests. The government''s decide to invest in education was welcomed."','',NULL,'grow → growth; succeed → success; cooperate → cooperation; fail to work → failure to produce results / failure of the medicine to work; decide → decision.','hard'),
  (cid,38,143,'production','[TOEFL Writing — 200 words] Write an academic paragraph on "Digital transformation in higher education." Use a two-level N+of+N chain, at least one possessive nominalization, at least 5 other nominalizations, and one instance where you deliberately avoid nominalization for clarity.','',NULL,'The acceleration of the adoption of digital technologies in higher education institutions represents a fundamental transformation of the educational landscape. The pandemic''s forced disruption of traditional teaching models accelerated the implementation of online and blended learning formats that had previously been considered supplementary. The development of digital competency among both students and faculty has emerged as a strategic priority across the sector. At the level of curriculum design, the integration of digital tools requires not only investment in infrastructure but also the reorganization of pedagogical approaches. However, universities should resist the temptation to digitize every aspect of the learning experience: some activities work better face to face. The assessment of learning outcomes in digital environments remains an area where further research is urgently needed, and the measurement of engagement — beyond simple completion rates — presents a significant methodological challenge.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
